mapper.select:
SELECT s.score_id, s.sid, s.course_id, s.usual, s.mid, s.final, s.total, s.gp, st.name AS student_name, c.name AS course_name, cl.name AS clazz_name, s.semester_id, sem.name AS semester_name, c.credit FROM score s LEFT JOIN student st ON s.sid = st.sid LEFT JOIN course c ON s.course_id = c.course_id LEFT JOIN clazz cl ON st.cid = cl.cid LEFT JOIN semester sem ON sem.id = s.semester_id WHERE s.sid = #{sid}
AND s.semester_id IS NULL
AND s.semester_id = #{semesterId}
ORDER BY s.score_id

mapper.update:
UPDATE score
SET sid = #{sid}, course_id = #{courseId}, semester_id = #{semesterId},
    usual = #{usual}, mid = #{mid}, final = #{finalScore},
    total = #{total}, gp = #{gp}
WHERE score_id = #{scoreId}

mapper.select:
SELECT COUNT(*)
FROM score
WHERE sid = #{sid} AND course_id = #{courseId}
  AND (semester_id <=> #{semesterId})

    AND score_id != #{excludeId}
